import {escapeHTML as e} from './markdown.js';
export const dateLabel = value => {const date=new Date(value+'T12:00:00Z');return Number.isNaN(date.getTime())?'Undated':new Intl.DateTimeFormat('en', {month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(date);};
export const topicLabel = value => value.replace(/-/g,' ').replace(/\b\w/g,c=>c.toUpperCase()).replace(/\b(Ai|Api|Nlp)\b/g,s=>s.toUpperCase()).replace(/Postgresql/g,'PostgreSQL').replace(/Whatsapp/g,'WhatsApp').replace(/Dataframe/g,'DataFrame');
export function visiblePosts(posts,{query='',topic='',source=''}={}){
 const words=query.trim().toLowerCase().split(/\s+/).filter(Boolean);
 return posts.filter(p=>(!topic||p.tags.includes(topic))&&(!source||(p.source||'Journal')===source)&&words.every(w=>[p.title,p.excerpt,...p.tags].join(' ').toLowerCase().includes(w))).sort((a,b)=>b.date.localeCompare(a.date));
}
export function postLink(p){
 if(p.source!=='Medium')return '/blog/'+encodeURIComponent(p.slug);
 try{const url=new URL(p.url);return url.protocol==='https:'&&url.hostname==='medium.com'?url.href:'https://medium.com/@andilembele';}catch{return 'https://medium.com/@andilembele';}
}
export function postCard(p,featured=false){return `<article class="${featured?'featured-post':'archive-post'}"><div class="post-date"><time datetime="${e(p.date)}">${dateLabel(p.date)}</time><span>${p.source==='Medium'?'Medium':'Journal'}</span></div><div><${featured?'h2':'h3'}><a href="${e(postLink(p))}">${e(p.title)} <span class="post-arrow" aria-hidden="true">${p.source==='Medium'?'↗':'→'}</span></a></${featured?'h2':'h3'}>${p.excerpt?`<p class="post-excerpt">${e(p.excerpt)}</p>`:''}<p class="post-topics">${p.tags.slice(0,3).map(t=>e(topicLabel(t))).join(' / ')}</p></div></article>`;}
export function archive(posts){let year='';return posts.map(p=>{const y=p.date.slice(0,4),heading=y!==year?`<h2 class="archive-year">${e(y)}</h2>`:'';year=y;return heading+postCard(p);}).join('');}
export function indexMarkup(posts){const sorted=visiblePosts(posts);return `<section class="blog-head"><a class="back-home" href="/">← About Andile</a><p class="eyebrow">Andile Jaden Mbele / Writing</p><h1>Writing.</h1><p class="about">Software, infrastructure, and data.</p><div class="writing-links"><a href="https://medium.com/@andilembele">Medium ↗</a><a href="https://rooibosradar.com/">Rooibos Radar ↗</a></div></section><section id="latest" aria-label="Latest article">${sorted.length?'<p class="small-heading">Latest</p>'+postCard(sorted[0],true):''}</section><section class="writing-archive" aria-label="Writing archive"><div class="archive-heading"><h2>All writing</h2><span id="post-count">${sorted.length} articles</span></div><form class="browse-controls" id="browse" role="search" hidden><label class="search-label">Search articles<input id="search" type="search" placeholder="Search writing…" autocomplete="off"></label><label>Topic<select id="topic"><option value="">All topics</option>${[...new Set(posts.flatMap(p=>p.tags))].sort().map(t=>`<option value="${e(t)}">${e(topicLabel(t))}</option>`).join('')}</select></label><label>Source<select id="source"><option value="">Everywhere</option><option value="Medium">Medium</option><option value="Journal">This website</option></select></label></form><div id="results">${archive(sorted)}</div><div class="archive-bottom"><p id="results-status" role="status"></p><button id="more" type="button" hidden>More articles ↓</button><button id="reset-filters" type="button" hidden>Clear filters</button></div></section><aside class="writing-signoff"><p>More from my corner of the internet.</p><a href="https://medium.com/@andilembele">Follow on Medium ↗</a></aside>`;}
